// Diagnostic ponctuel des données brutes de sondes JK02_32S.
// Aucun changement de validation, de connexion BLE ou de paramètres BMS.
const frame=msg.payload||{};
if(frame.type!==2||frame.crc_ok!==true||typeof frame.raw_hex!=="string"
   ||!/^[0-9a-fA-F]{600}$/.test(frame.raw_hex))return null;
const mac=String(frame.address||"").toUpperCase();if(!mac)return null;
const now=Date.now(),key="last_raw_temperature:"+mac;
if(now-(context.get(key)||0)<20000)return null;
const b=Buffer.from(frame.raw_hex,"hex");
if(b.length!==300||b.subarray(0,4).toString("hex")!=="55aaeb90")return null;
context.set(key,now);
const temps=[
 {label:"T1",offset:162},{label:"T2",offset:164},{label:"MOS",offset:144}
].map(x=>{const raw=b.readInt16LE(x.offset),c=raw/10;
 return {...x,raw,c,valid:c>=-80&&c<=160};});
const invalid=temps.filter(x=>!x.valid);
const count=Array.from({length:32},(_,i)=>((b.readUInt32LE(70)>>>i)&1)).reduce((s,x)=>s+x,0);
const pack=b.readUInt32LE(150)/1000,soc=b[173],absent=b[214];
const tail=mac.slice(-5);
const display=temps.map(x=>x.label+"="+(x.valid?x.c.toFixed(1)+"°C":x.c.toFixed(1)+"°C!"));
const line1=tail+" | "+display.join(" | ");
const line2=tail+" | invalides="+invalid.map(x=>x.label).join(",")+
  " ("+invalid.length+"/3) | absence-mask=0x"+absent.toString(16).padStart(2,"0").toUpperCase()+
  " | "+count+" cell. | "+pack.toFixed(2)+"V | SOC "+soc+"%";
node.status({fill:invalid.length?"yellow":"green",shape:invalid.length?"ring":"dot",
text:tail+" "+(invalid.length?invalid.map(x=>x.label).join(",")+" invalide":"3 températures valides")});
return [[
 {topic:"jk/"+mac+"/temperatures_brutes",payload:line1},
 {topic:"jk/"+mac+"/sondes_statut",payload:line2}
]];
